/**
 * Expo config plugin: reproducible release signing.
 *
 * `android/` is generated by prebuild and is not in version control, so a hand
 * edit to `app/build.gradle` disappears the next time anyone regenerates it.
 * This plugin reapplies the change every prebuild, which is what makes the
 * release build reproducible on another machine.
 *
 * No secret lives here. The keystore path and passwords arrive as Gradle
 * properties at build time:
 *
 *   ./gradlew assembleRelease \
 *     -PKEEPTRAIL_STORE_FILE=/absolute/path/keeptrail-release.jks \
 *     -PKEEPTRAIL_STORE_PASSWORD=... \
 *     -PKEEPTRAIL_KEY_ALIAS=keeptrail \
 *     -PKEEPTRAIL_KEY_PASSWORD=...
 *
 * With those properties absent the release build falls back to debug signing,
 * so `assembleRelease` still works for a contributor who has no keystore — it
 * simply produces an artifact that cannot be distributed, which is the correct
 * outcome rather than a build failure.
 */

const { withAppBuildGradle } = require("expo/config-plugins");

const SIGNING_CONFIG = `        release {
            if (project.hasProperty('KEEPTRAIL_STORE_FILE')) {
                storeFile file(project.property('KEEPTRAIL_STORE_FILE'))
                storePassword project.property('KEEPTRAIL_STORE_PASSWORD')
                keyAlias project.property('KEEPTRAIL_KEY_ALIAS')
                keyPassword project.property('KEEPTRAIL_KEY_PASSWORD')
            }
        }
        debug {`;

const RELEASE_SIGNING_SELECTOR =
  "signingConfig project.hasProperty('KEEPTRAIL_STORE_FILE') ? signingConfigs.release : signingConfigs.debug";

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (modConfig) => {
    let contents = modConfig.modResults.contents;

    // 1. Add a `release` signing config alongside the generated `debug` one.
    if (!contents.includes("KEEPTRAIL_STORE_FILE")) {
      const debugBlockStart = "    signingConfigs {\n        debug {";
      if (!contents.includes(debugBlockStart)) {
        throw new Error(
          "with-release-signing: the generated signingConfigs block does not have the " +
            "expected shape. Expo's template changed; update this plugin rather than " +
            "shipping a debug-signed release.",
        );
      }
      contents = contents.replace(debugBlockStart, `    signingConfigs {\n${SIGNING_CONFIG}`);
    }

    // 2. Point the release build type at it.
    const templateSelector =
      /release \{\s*\n(\s*)\/\/ Caution! In production[\s\S]*?signingConfig signingConfigs\.debug/;
    if (templateSelector.test(contents)) {
      contents = contents.replace(templateSelector, `release {\n$1${RELEASE_SIGNING_SELECTOR}`);
    } else if (!contents.includes(RELEASE_SIGNING_SELECTOR)) {
      throw new Error(
        "with-release-signing: could not point the release build type at the release " +
          "signing config. Refusing to leave a release build signed with the debug key.",
      );
    }

    modConfig.modResults.contents = contents;
    return modConfig;
  });
};
